$ErrorActionPreference='Stop';$root=Split-Path -Parent $MyInvocation.MyCommand.Path
$types=@{'.html'='text/html; charset=utf-8';'.js'='text/javascript; charset=utf-8';'.css'='text/css; charset=utf-8';'.json'='application/json; charset=utf-8';'.png'='image/png';'.jpg'='image/jpeg';'.jpeg'='image/jpeg';'.svg'='image/svg+xml';'.woff2'='font/woff2';'.pdf'='application/pdf'}
$listener=[System.Net.Sockets.TcpListener]::new([System.Net.IPAddress]::Loopback,4173);$listener.Start()
Write-Host 'Local server: http://127.0.0.1:4173/' -ForegroundColor Cyan;Write-Host 'Press Ctrl+C to stop.'
try{while($true){$client=$listener.AcceptTcpClient();try{$stream=$client.GetStream();$reader=[System.IO.StreamReader]::new($stream,[Text.Encoding]::ASCII,$false,4096,$true);$request=$reader.ReadLine();while(($line=$reader.ReadLine()) -ne ''){if($null -eq $line){break}};if([string]::IsNullOrWhiteSpace($request)){continue};$target=($request -split ' ')[1];$uri=[Uri]::new("http://127.0.0.1$target");$relative=[Uri]::UnescapeDataString($uri.AbsolutePath).TrimStart('/');if(!$relative -or $relative.EndsWith('/')){$relative+='index.html'};$file=[IO.Path]::GetFullPath((Join-Path $root $relative));$prefix=[IO.Path]::GetFullPath($root)+[IO.Path]::DirectorySeparatorChar;if(!$file.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){$status='403 Forbidden';$body=[Text.Encoding]::UTF8.GetBytes('Forbidden');$type='text/plain'}elseif(![IO.File]::Exists($file)){$status='404 Not Found';$body=[Text.Encoding]::UTF8.GetBytes('Not found');$type='text/plain'}else{$status='200 OK';$body=[IO.File]::ReadAllBytes($file);$ext=[IO.Path]::GetExtension($file).ToLowerInvariant();$type=if($types.ContainsKey($ext)){$types[$ext]}else{'application/octet-stream'}};$header=[Text.Encoding]::ASCII.GetBytes("HTTP/1.1 $status`r`nContent-Type: $type`r`nContent-Length: $($body.Length)`r`nCache-Control: no-store`r`nConnection: close`r`n`r`n");$stream.Write($header,0,$header.Length);$stream.Write($body,0,$body.Length);$stream.Flush()}catch{Write-Host $_.Exception.Message -ForegroundColor DarkYellow}finally{$client.Close()}}}finally{$listener.Stop()}
